mapper.select:
WHERE
AND v.status = 'available' AND LOCATE(#{query}, v.name) > 0 AND (r.kind <> 'plugin' OR r.source <> 'builtin' OR r.published_version_id = v.id)
AND r.kind = 'agent' AND JSON_UNQUOTE(JSON_EXTRACT(v.config_json, '$.agentType')) IN ('chat', 'task') AND COALESCE(JSON_LENGTH(JSON_EXTRACT(v.config_json, '$.workflowVersionIds')), 0) = 0
AND r.id = #{resourceId}
AND NOT EXISTS ( SELECT 1 FROM resource_version newer WHERE newer.enterprise_id = v.enterprise_id AND newer.resource_id = v.resource_id AND newer.status = 'available' AND newer.version_no > v.version_no
AND JSON_UNQUOTE(JSON_EXTRACT(newer.config_json, '$.agentType')) IN ('chat', 'task') AND COALESCE(JSON_LENGTH(JSON_EXTRACT(newer.config_json, '$.workflowVersionIds')), 0) = 0
)
AND (v.published_at < #{cursor.time} OR (v.published_at = #{cursor.time} AND v.id < #{cursor.id}))
ORDER BY v.published_at DESC, v.id DESC LIMIT #{limit}


WHERE

  
  

AND v.status = 'available' AND v.id IN
#{id}
